def format_eta_minutes(minutes: float) -> str:
    """Format a number of minutes as a human-readable ETA, e.g. 244 -> '4 hrs 4 min'."""
    mins = max(1, int(minutes))
    hours, rem = divmod(mins, 60)
    if hours and rem:
        return f"{hours} hrs {rem} min"
    if hours:
        return f"{hours} hrs"
    return f"{mins} min"


